CREATE TABLE "content_drafts" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"company_id" uuid NOT NULL,
	"platform" text NOT NULL,
	"format" text NOT NULL,
	"pillar" text DEFAULT '' NOT NULL,
	"campaign" text DEFAULT '' NOT NULL,
	"topic" text NOT NULL,
	"title" text DEFAULT '' NOT NULL,
	"body" text DEFAULT '' NOT NULL,
	"hashtags" text[] DEFAULT '{}'::text[] NOT NULL,
	"call_to_action" text DEFAULT '' NOT NULL,
	"image_prompt" text DEFAULT '' NOT NULL,
	"video_script" text DEFAULT '' NOT NULL,
	"status" text DEFAULT 'draft' NOT NULL,
	"version" integer DEFAULT 1 NOT NULL,
	"generated_version" integer,
	"claims" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"facts_used" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"knowledge_used" uuid[] DEFAULT '{}'::uuid[] NOT NULL,
	"plan_version" integer,
	"claims_acknowledged_by_user_id" text,
	"claims_acknowledged_at" timestamp with time zone,
	"approved_by_user_id" text,
	"approved_at" timestamp with time zone,
	"approved_version" integer,
	"rejected_by_user_id" text,
	"rejected_at" timestamp with time zone,
	"rejection_note" text,
	"created_by_user_id" text NOT NULL,
	"updated_by_user_id" text NOT NULL,
	"planned_for" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "content_drafts_company_id_id_unique" UNIQUE("company_id","id"),
	CONSTRAINT "content_drafts_platform_known" CHECK ("content_drafts"."platform" IN ('linkedin', 'facebook', 'x', 'youtube')),
	CONSTRAINT "content_drafts_format_known" CHECK ("content_drafts"."format" IN ('post', 'image_post', 'video')),
	CONSTRAINT "content_drafts_status_known" CHECK ("content_drafts"."status" IN ('idea', 'draft', 'approved', 'rejected', 'scheduled', 'published', 'failed', 'archived')),
	CONSTRAINT "content_drafts_youtube_takes_video" CHECK ("content_drafts"."platform" <> 'youtube' OR "content_drafts"."format" = 'video'),
	CONSTRAINT "content_drafts_title_youtube_only" CHECK ("content_drafts"."platform" = 'youtube' OR "content_drafts"."title" = ''),
	CONSTRAINT "content_drafts_script_video_only" CHECK ("content_drafts"."format" = 'video' OR "content_drafts"."video_script" = ''),
	CONSTRAINT "content_drafts_no_image_prompt_on_text_post" CHECK ("content_drafts"."format" <> 'post' OR "content_drafts"."image_prompt" = ''),
	CONSTRAINT "content_drafts_topic_length" CHECK (char_length("content_drafts"."topic") BETWEEN 1 AND 500),
	CONSTRAINT "content_drafts_pillar_length" CHECK (char_length("content_drafts"."pillar") <= 200),
	CONSTRAINT "content_drafts_campaign_length" CHECK (char_length("content_drafts"."campaign") <= 200),
	CONSTRAINT "content_drafts_title_length" CHECK (char_length("content_drafts"."title") <= 100),
	CONSTRAINT "content_drafts_body_length" CHECK (char_length("content_drafts"."body") <= 63206),
	CONSTRAINT "content_drafts_call_to_action_length" CHECK (char_length("content_drafts"."call_to_action") <= 300),
	CONSTRAINT "content_drafts_image_prompt_length" CHECK (char_length("content_drafts"."image_prompt") <= 2000),
	CONSTRAINT "content_drafts_video_script_length" CHECK (char_length("content_drafts"."video_script") <= 10000),
	CONSTRAINT "content_drafts_hashtags_count" CHECK (cardinality("content_drafts"."hashtags") <= 30),
	CONSTRAINT "content_drafts_hashtags_length" CHECK (char_length(array_to_string("content_drafts"."hashtags", '')) <= 1800),
	CONSTRAINT "content_drafts_claims_is_array" CHECK (jsonb_typeof("content_drafts"."claims") = 'array'),
	CONSTRAINT "content_drafts_claims_size" CHECK (char_length("content_drafts"."claims"::text) <= 50000),
	CONSTRAINT "content_drafts_facts_used_is_array" CHECK (jsonb_typeof("content_drafts"."facts_used") = 'array'),
	CONSTRAINT "content_drafts_knowledge_used_count" CHECK (cardinality("content_drafts"."knowledge_used") <= 10),
	CONSTRAINT "content_drafts_version_positive" CHECK ("content_drafts"."version" >= 1),
	CONSTRAINT "content_drafts_generated_version_range" CHECK ("content_drafts"."generated_version" BETWEEN 1 AND "content_drafts"."version"),
	CONSTRAINT "content_drafts_idea_has_no_content" CHECK ("content_drafts"."status" <> 'idea' OR ("content_drafts"."title" = '' AND "content_drafts"."body" = '' AND "content_drafts"."call_to_action" = '' AND "content_drafts"."image_prompt" = '' AND "content_drafts"."video_script" = '' AND cardinality("content_drafts"."hashtags") = 0)),
	CONSTRAINT "content_drafts_approval_fields_together" CHECK (num_nonnulls("content_drafts"."approved_by_user_id", "content_drafts"."approved_at", "content_drafts"."approved_version") IN (0, 3)),
	CONSTRAINT "content_drafts_approved_has_approval" CHECK ("content_drafts"."status" <> 'approved' OR ("content_drafts"."approved_by_user_id" IS NOT NULL AND "content_drafts"."approved_version" = "content_drafts"."version")),
	CONSTRAINT "content_drafts_unapproved_has_no_approval" CHECK ("content_drafts"."status" NOT IN ('idea', 'draft', 'rejected', 'archived') OR "content_drafts"."approved_by_user_id" IS NULL),
	CONSTRAINT "content_drafts_approved_version_range" CHECK ("content_drafts"."approved_version" BETWEEN 1 AND "content_drafts"."version"),
	CONSTRAINT "content_drafts_acknowledgment_fields_together" CHECK (num_nonnulls("content_drafts"."claims_acknowledged_by_user_id", "content_drafts"."claims_acknowledged_at") IN (0, 2)),
	CONSTRAINT "content_drafts_acknowledgment_with_approval" CHECK ("content_drafts"."claims_acknowledged_at" IS NULL OR "content_drafts"."approved_at" IS NOT NULL),
	CONSTRAINT "content_drafts_rejection_fields_together" CHECK (num_nonnulls("content_drafts"."rejected_by_user_id", "content_drafts"."rejected_at") IN (0, 2)),
	CONSTRAINT "content_drafts_rejection_note_with_rejection" CHECK ("content_drafts"."rejection_note" IS NULL OR "content_drafts"."rejected_at" IS NOT NULL),
	CONSTRAINT "content_drafts_rejection_note_length" CHECK (char_length("content_drafts"."rejection_note") BETWEEN 1 AND 500),
	CONSTRAINT "content_drafts_rejected_has_rejection" CHECK ("content_drafts"."status" <> 'rejected' OR "content_drafts"."rejected_by_user_id" IS NOT NULL)
);
